import React from "react";
import './skills.css';
import { motion } from 'framer-motion';

import UIDesign from '../../assets/ui-design.png';
import WebDesign from '../../assets/website-design.png';
import AppDesign from '../../assets/app-design.png';

import HTML5img from '../../assets/html5.svg';
import CSSimg from '../../assets/css3.svg';
import JSimg from '../../assets/javascript.svg';
import JavaImg from '../../assets/java.svg';
import PHPimg from '../../assets/php-original.svg';
import SQLimg from '../../assets/mysql-original-wordmark.svg';
import CsharpImg from '../../assets/csharp-original.svg';

const services = [
  {
    image: UIDesign,
    title: 'UI/UX Design',
    description:
      'Designing clean, intuitive interfaces with a strong focus on usability, clarity, and polished user experience.',
  },
  {
    image: WebDesign,
    title: 'Web Development',
    description:
      'Building responsive web applications and internal systems with strong structure, practical functionality, and maintainable front-end design.',
  },
  {
    image: AppDesign,
    title: 'Software & App Development',
    description:
      'Developing practical software solutions across full-stack systems, internal tools, and app-based projects from concept through implementation.',
  },
];

const techStack = [
  { image: HTML5img, label: 'HTML5' },
  { image: CSSimg, label: 'CSS3' },
  { image: JSimg, label: 'JavaScript' },
  { image: CsharpImg, label: 'C# / .NET' },
  { image: JavaImg, label: 'Java' },
  { image: PHPimg, label: 'PHP' },
  { image: SQLimg, label: 'SQL / MySQL' },
];

const additionalTech = [
  '.NET',
  'ASP.NET Core',
  'Razor Pages',
  'MVC',
  'React',
  'Bootstrap',
  'Entity Framework Core',
  'SQL Server',
  'Git',
  'GitHub',
  'Laravel',
  'Vite',
  'Firebase',
  'Supabase',
  'Vercel',
  'Unity',
  'AWS',
  'UI/UX',
];

const fadeUp = {
  hidden: { opacity: 0, y: 24 },
  visible: { opacity: 1, y: 0 },
};

const Skills = () => {
  return (
    <section id="skills">
      <div className="skills-container">
        <motion.p
          className="skills-eyebrow"
          variants={fadeUp}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.3 }}
          transition={{ duration: 0.5 }}
        >
          What I Do
        </motion.p>

        <motion.h2
          className="skillTitle"
          variants={fadeUp}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.3 }}
          transition={{ duration: 0.55, delay: 0.05 }}
        >
          Building practical digital solutions with design and development in mind
        </motion.h2>

        <motion.p
          className="skillDesc"
          variants={fadeUp}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.3 }}
          transition={{ duration: 0.55, delay: 0.1 }}
        >
          I work across development and design, combining technical problem-solving with a strong eye
          for usability, structure, and presentation. My experience includes building websites,
          applications, and internal business systems that are functional, polished, and genuinely useful.
        </motion.p>

        <div className="skillBars">
          {services.map((service, index) => (
            <motion.article
              className="skillBar"
              key={index}
              variants={fadeUp}
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true, amount: 0.2 }}
              transition={{ duration: 0.5, delay: index * 0.08 }}
            >
              <div className="skillBarIconWrap">
                <img src={service.image} alt={service.title} className="skillBarImg" />
              </div>

              <div className="skillBarText">
                <h3>{service.title}</h3>
                <p>{service.description}</p>
              </div>
            </motion.article>
          ))}
        </div>

        <motion.div
          className="experienceBlock"
          variants={fadeUp}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.2 }}
          transition={{ duration: 0.55 }}
        >
          <p className="skills-eyebrow">Experience</p>
          <h3 className="experienceTitle">Real-world development experience</h3>
          <p className="experienceDesc">
            In my role within Digital Transformation at the Royal Orthopaedic Hospital, I contribute
            to building and improving internal systems that replace outdated or manual processes.
            My work has involved C#, ASP.NET Core, Razor, SQL Server, Bootstrap, and developing
            practical solutions around real stakeholder and user needs.
          </p>

          <div className="experiencePoints">
            <div className="experiencePoint">Build and improve internal web-based systems</div>
            <div className="experiencePoint">Translate stakeholder requirements into working solutions</div>
            <div className="experiencePoint">Work across planning, development, testing, and refinement</div>
            <div className="experiencePoint">Balance functionality, usability, and maintainability</div>
          </div>
        </motion.div>

        <div className="techSection">
          <motion.div
            className="techSectionHeader"
            variants={fadeUp}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true, amount: 0.25 }}
            transition={{ duration: 0.55 }}
          >
            <p className="skills-eyebrow">Tech Stack</p>
            <h3 className="techTitle">Technologies I use to build real-world systems</h3>
            <p className="techDesc">
              A mix of technologies I have used across personal, academic, and professional development work.
            </p>
          </motion.div>

          <div className="techGrid">
            {techStack.map((tech, index) => (
              <motion.div
                className="techCard"
                key={index}
                variants={fadeUp}
                initial="hidden"
                whileInView="visible"
                viewport={{ once: true, amount: 0.15 }}
                transition={{ duration: 0.45, delay: index * 0.06 }}
              >
                <div className="techIconWrap">
                  <img src={tech.image} alt={tech.label} className="techIcon" />
                </div>
                <span className="techLabel">{tech.label}</span>
              </motion.div>
            ))}
          </div>

          <motion.div
            className="additionalTech"
            variants={fadeUp}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true, amount: 0.2 }}
            transition={{ duration: 0.5, delay: 0.1 }}
          >
            {additionalTech.map((item, index) => (
              <span className="additionalTechPill" key={index}>
                {item}
              </span>
            ))}
          </motion.div>
        </div>
      </div>
    </section>
  );
};

export default Skills;