import React, { useRef, useState } from 'react';
import './contact.css';
import LinkedInIcon from '../../assets/LinkedInIcon.png';
import emailjs from '@emailjs/browser';
import { motion } from 'framer-motion';

const fadeUp = {
  hidden: { opacity: 0, y: 24 },
  visible: { opacity: 1, y: 0 },
};

const Contact = () => {
  const form = useRef();
  const [statusMessage, setStatusMessage] = useState('');
  const [isSending, setIsSending] = useState(false);

  const sendEmail = (e) => {
    e.preventDefault();

    setIsSending(true);
    setStatusMessage('');

    emailjs
      .sendForm(
        'service_ck4gi4h',
        'template_nk9u7gb',
        form.current,
        'Hgiw3sO_8FBIjr01O'
      )
      .then(
        () => {
          e.target.reset();
          setStatusMessage('Your message has been sent successfully.');
          setIsSending(false);
        },
        () => {
          setStatusMessage('Something went wrong while sending your message. Please try again.');
          setIsSending(false);
        }
      );
  };

  return (
    <section id="contactPage">
      <div id="contact" className="contactContainer">
        <motion.p
          className="contactEyebrow"
          variants={fadeUp}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.3 }}
          transition={{ duration: 0.5 }}
        >
          Contact
        </motion.p>

        <motion.h2
          className="contactPageTitle"
          variants={fadeUp}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.3 }}
          transition={{ duration: 0.55, delay: 0.05 }}
        >
          Let&apos;s build something great
        </motion.h2>

        <motion.p
          className="contactDesc"
          variants={fadeUp}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.3 }}
          transition={{ duration: 0.55, delay: 0.1 }}
        >
          Whether you have a project in mind, want to collaborate, or simply want to say hello,
          feel free to send me a message.
        </motion.p>

        <motion.div
          className="contactCard"
          variants={fadeUp}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.2 }}
          transition={{ duration: 0.55 }}
        >
          <form className="contactForm" ref={form} onSubmit={sendEmail}>
            <div className="inputGroup">
              <input
                type="text"
                className="name"
                placeholder="Your Name"
                name="your_name"
                required
              />
              <input
                type="email"
                className="email"
                placeholder="Your Email"
                name="your_email"
                required
              />
            </div>

            <textarea
              className="message"
              name="message"
              rows="6"
              placeholder="Your Message"
              required
            />

            <div className="contactActions">
              <button type="submit" className="submitBtn" disabled={isSending}>
                {isSending ? 'Sending...' : 'Send Message'}
              </button>

              <div className="links">
                <a
                  href="https://www.linkedin.com/in/mohamed-irfan-arshad-5b7556290"
                  target="_blank"
                  rel="noopener noreferrer"
                  aria-label="Visit LinkedIn profile"
                  className="socialLink"
                >
                  <img src={LinkedInIcon} alt="LinkedIn" className="link" />
                </a>
              </div>
            </div>

            {statusMessage && <p className="formStatus">{statusMessage}</p>}
          </form>
        </motion.div>
      </div>
    </section>
  );
};

export default Contact;