import React from 'react';
import './intro.css';
import bg from '../../assets/Me.png';
import btnImg from '../../assets/hireme.png';
import cv from '../../assets/Tech CV - ATS Friendly - 2026.pdf';
import { useTypewriter, Cursor } from 'react-simple-typewriter';
import { motion } from 'framer-motion';

const Intro = () => {
  const [typeEffect] = useTypewriter({
    words: ['Software Developer', 'Web Developer', 'Game Developer', 'App Developer'],
    loop: {},
    typeSpeed: 100,
    deleteSpeed: 40,
  });

  return (
    <section id="intro">
      <div className="introInner">
        <motion.div
          className="introContent"
          initial={{ opacity: 0, y: 28 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.7, ease: 'easeOut' }}
        >
          <p className="introEyebrow">Portfolio</p>

          <span className="hello">Hello, I’m</span>

          <h1 className="introHeading">
            <span className="introName">Irfan Arshad</span>
          </h1>

          <span className="introCred">
            2+ years building production systems • NHS Digital Transformation
          </span>

          <div className="introRoleWrap">
            <span className="introRole">{typeEffect}</span>
            <Cursor />
          </div>

          <p className="introPara">
            I design and build production-ready applications, from internal business systems to full-stack web platforms, combining strong technical development with a focus on usability, performance, and real-world impact.
          </p>

          <motion.div
            className="introActions"
            initial={{ opacity: 0, y: 18 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.2, ease: 'easeOut' }}
          >
            <button
              className="btn primaryBtn"
              onClick={() => {
                document.getElementById('contact').scrollIntoView({ behavior: 'smooth' });
              }}
            >
              <img src={btnImg} alt="Hire Me" className="btnImg" />
              Let&apos;s Talk
            </button>

            <a href={cv} download="Tech CV - ATS Friendly - 2026.pdf" className="cvLink">
              <button className="btn secondaryBtn">Download CV</button>
            </a>
          </motion.div>
        </motion.div>

        <motion.div
          className="introVisual"
          initial={{ opacity: 0, x: 32 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.8, delay: 0.15, ease: 'easeOut' }}
        >
          <div className="introImageGlow"></div>
          <img src={bg} alt="Irfan Arshad" className="bg" />
        </motion.div>
      </div>
    </section>
  );
};

export default Intro;