import React from 'react';
import './experience.css';
import { motion } from 'framer-motion';

const timelineData = [
  {
    period: '2024 – Present',
    title: 'Systems & Application Developer',
    org: 'Royal Orthopaedic Hospital NHS',
    description:
      'Designing and delivering production-grade internal systems used by clinical and administrative teams. Working end-to-end across requirements gathering, system design, development, testing, and deployment, with a strong focus on usability, data accuracy, and real-world impact.',
    highlights: [
      'Built and deployed multiple internal systems replacing manual processes',
      'Worked across C#, ASP.NET Core, Razor, EF Core, and SQL Server',
      'Improved efficiency and data accuracy for clinical workflows',
      'Operated in a hands-on, ownership-driven development role',
    ],
  },
  {
    period: '2023 – Present',
    title: 'Full-Stack & Personal Projects',
    org: 'Independent Development',
    description:
      'Designed and built a range of full-stack applications, mobile apps, and interactive systems. Focused on solving real problems through automation, clean UI, and strong system logic.',
    highlights: [
      'Built full-stack systems using React, PHP, Firebase, and Supabase',
      'Developed a league automation system replacing manual workflows',
      'Created mobile and web apps with real-world use cases',
      'Worked across frontend, backend, and database design',
    ],
  },
  {
    period: '2018 – 2023',
    title: 'BSc Computer Science (Upper Class Honours)',
    org: 'Aston University',
    description:
      'Developed a strong foundation in software development, systems design, and problem solving. Gained experience across multiple languages, frameworks, and project-based learning environments.',
    highlights: [
      'Built projects across Java, C#, PHP, and web technologies',
      'Developed understanding of software architecture and databases',
      'Worked on practical, end-to-end development projects',
      'Built foundation for full-stack and systems development',
    ],
  },
];

const fadeUp = {
  hidden: { opacity: 0, y: 24 },
  visible: { opacity: 1, y: 0 },
};

const Experience = () => {
  return (
    <section id="experience">
      <div className="experience-container">
        <motion.p
          className="experience-eyebrow"
          variants={fadeUp}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.3 }}
          transition={{ duration: 0.5 }}
        >
          Experience
        </motion.p>

        <motion.h2
          className="experience-main-title"
          variants={fadeUp}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.3 }}
          transition={{ duration: 0.55, delay: 0.05 }}
        >
          My development journey so far
        </motion.h2>

        <motion.p
          className="experience-main-desc"
          variants={fadeUp}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.3 }}
          transition={{ duration: 0.55, delay: 0.1 }}
        >
          A snapshot of how my experience has developed across professional work, practical projects, and technical growth.
        </motion.p>

        <div className="timeline">
          {timelineData.map((item, index) => (
            <motion.article
              className="timeline-item"
              key={index}
              variants={fadeUp}
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true, amount: 0.2 }}
              transition={{ duration: 0.5, delay: index * 0.08 }}
            >
              <div className="timeline-marker">
                <span className="timeline-dot"></span>
                {index !== timelineData.length - 1 && <span className="timeline-line"></span>}
              </div>

              <div className="timeline-card">
                <span className="timeline-period">{item.period}</span>
                <h3 className="timeline-title">{item.title}</h3>
                <p className="timeline-org">{item.org}</p>
               <p className="timeline-description">{item.description}</p>

                <ul className="timeline-highlights">
                {item.highlights.map((point, i) => (
                    <li key={i}>{point}</li>
                ))}
                </ul>
              </div>
            </motion.article>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Experience;