import React, { useState } from 'react';
import './projects.css';
import { ChevronRight, ChevronLeft, Github, Check, ZoomIn, X } from 'lucide-react';
import { motion } from 'framer-motion';

import InTheShadows1 from '../../assets/InTheShadows1.png';
import InTheShadows2 from '../../assets/InTheShadows2.png';
import InTheShadows3 from '../../assets/InTheShadows3.png';
import InTheShadows4 from '../../assets/InTheShadows4.png';
import InTheShadows5 from '../../assets/InTheShadows5.png';
import InTheShadows6 from '../../assets/InTheShadows6.png';
import Settings from '../../assets/FinanceManagementApp/Settings.png';
import Overview from '../../assets/FinanceManagementApp/Overview.png';
import SessionDetails from '../../assets/FinanceManagementApp/SessionDetails.png';
import SessionList from '../../assets/FinanceManagementApp/SessionList.png';
import SessionsFinanceOverview from '../../assets/FinanceManagementApp/SessionsFinanceOverview.png';
import HomeScreen from '../../assets/HotSpotsApp/HomeScreen.jpeg';
import MainMap from '../../assets/HotSpotsApp/MainMap.jpeg';
import AddNewHotSpot from '../../assets/HotSpotsApp/AddNewHotSpot.jpeg';
import AddFilled from '../../assets/HotSpotsApp/AddFilled.jpeg';
import Zoomed from '../../assets/HotSpotsApp/Zoomed.jpeg';
import RMS7 from '../../assets/ResultsManagementsSys/RMS7.png';
import RMS2 from '../../assets/ResultsManagementsSys/RMS2.png';
import RMS3 from '../../assets/ResultsManagementsSys/RMS3.png';
import RMS5 from '../../assets/ResultsManagementsSys/RMS5.png';
import RMS6 from '../../assets/ResultsManagementsSys/RMS6.png';

const projectData = [
  {
    title: 'HotSpots – City Discovery App',
    description:
      'A mobile app for discovering local attractions based on user interests and location.',
    features: [
      'Location-based suggestions',
      'Save & favourite spots',
      'Interactive map and filters',
    ],
    techStack: ['React Native', 'Firebase', 'Google Maps API'],
    images: [
      HomeScreen,
      MainMap,
      AddNewHotSpot,
      AddFilled,
      Zoomed,
    ],
    github: 'https://github.com/Irfan-Arshad/hotspots',
  },
  {
    title: 'In The Shadows - 3D Horror Game',
    description:
      'First-person 3D horror game featuring immersive visuals, puzzles, and AI-driven enemies.',
    features: [
      '3D immersive surround sound',
      'Custom enemy AI',
      'Psychological horror gameplay',
    ],
    techStack: ['Unity', 'C#', '.NET'],
    images: [
      InTheShadows1,
      InTheShadows2,
      InTheShadows3,
      InTheShadows4,
      InTheShadows5,
      InTheShadows6,
    ],
    github: 'https://github.com/Irfan-Arshad/InTheShadows',
  },
  {
    title: 'Birmingham League – Results Manager',
    description:
      'A web app for managing Birmingham badminton league results and live standings. No more manual input, league tables automatically update and compute positions after uploading the scorecard',
    features: [
      'Admin dashboard & total league management',
      'Fully automated live standings updates',
      'Algorithms to determine winner',
    ],
    techStack: ['PHP', 'VS Code', 'HTML', 'CSS'],
    images: [
      RMS2,
      RMS3,
      RMS5,
      RMS6,
      RMS7,
    ],
    github: 'https://github.com/Irfan-Arshad/birmingham-league',
  },
  {
    title: 'Aston Animal Sanctuary – Adopt an Animal',
    description:
      'A database-driven website allowing users to view and adopt animals.',
    features: [
      'Animal listings and filtering',
      'Admin dashboard',
      'Focus on UI/UX design and Backend',
      'User Roles, Logins and Auth',
    ],
    techStack: ['PHP', 'SQL', 'Laravel'],
    github: 'https://github.com/Irfan-Arshad/AstonAnimalSanctuary',
  },
  {
    title: 'Badminton Club Finance Manager (Beta)',
    description:
      'A mobile app for managing my badminton club finances. It tracks court and shuttle costs as well as player payments for each session.',
    features: [
      'Profit and loss statements',
      'Payment tracking',
      'Session-level information',
    ],
    techStack: ['React', 'Vite', 'Supabase', 'Vercel'],
    images: [
      SessionList,
      SessionDetails,
      Overview,
      SessionsFinanceOverview,
      Settings,
    ],
    github: 'https://github.com/Irfan-Arshad/badminton-club',
  },
];

const fadeUp = {
  hidden: { opacity: 0, y: 28 },
  visible: { opacity: 1, y: 0 },
};

const Projects = () => {
  const [index, setIndex] = useState(0);
  const [imageIndex, setImageIndex] = useState(0);
  const [lightboxOpen, setLightboxOpen] = useState(false);

  const project = projectData[index];
  const hasImages = project.images && project.images.length > 0;
  const hasVideo = !!project.video;

  const nextProject = () => {
    setIndex((prevIndex) => (prevIndex + 1) % projectData.length);
    setImageIndex(0);
    setLightboxOpen(false);
  };

  const prevProject = () => {
    setIndex((prevIndex) => (prevIndex - 1 + projectData.length) % projectData.length);
    setImageIndex(0);
    setLightboxOpen(false);
  };

  const nextImage = () => {
    if (!hasImages) return;
    setImageIndex((prev) => (prev + 1) % project.images.length);
  };

  const prevImage = () => {
    if (!hasImages) return;
    setImageIndex((prev) => (prev - 1 + project.images.length) % project.images.length);
  };

  const openLightbox = () => {
    if (hasImages) setLightboxOpen(true);
  };

  const closeLightbox = () => {
    setLightboxOpen(false);
  };

  return (
    <section id="projectsPage">
      <div id="projects" className="projects-container">
        <motion.p
          className="projects-eyebrow"
          variants={fadeUp}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.3 }}
          transition={{ duration: 0.5 }}
        >
          Portfolio
        </motion.p>

        <motion.h1
          className="projectTitle"
          variants={fadeUp}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.3 }}
          transition={{ duration: 0.55, delay: 0.05 }}
        >
          Past Projects
        </motion.h1>

        <motion.p
          className="projectDesc"
          variants={fadeUp}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.3 }}
          transition={{ duration: 0.55, delay: 0.1 }}
        >
          A selection of projects I have built across web, mobile, and game development.
        </motion.p>

        <div className="projects-showcase">
          <button
            onClick={prevProject}
            className="carousel-btn carousel-btn-left"
            aria-label="Previous project"
          >
            <ChevronLeft size={24} />
          </button>

          <motion.div
            className="project-card"
            key={index}
            variants={fadeUp}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: false, amount: 0.2 }}
            transition={{ duration: 0.5 }}
          >
            <div className="project-card-top">
              <span className="project-counter">
                {String(index + 1).padStart(2, '0')} / {String(projectData.length).padStart(2, '0')}
              </span>
            </div>

            <div className="project-grid">
              <div className="project-visual">
                <div className="image-frame">
                  {hasImages ? (
                    <>
                      <img
                        src={project.images[imageIndex]}
                        alt={`${project.title} screenshot ${imageIndex + 1}`}
                        className="project-image"
                        onClick={openLightbox}
                      />

                      <button
                        type="button"
                        className="zoom-btn"
                        onClick={openLightbox}
                        aria-label="Enlarge image"
                      >
                        <ZoomIn size={18} />
                      </button>

                      {project.images.length > 1 && (
                        <>
                          <div className="image-nav">
                            <button
                              onClick={prevImage}
                              className="image-btn"
                              aria-label="Previous image"
                            >
                              <ChevronLeft size={18} />
                            </button>
                            <button
                              onClick={nextImage}
                              className="image-btn"
                              aria-label="Next image"
                            >
                              <ChevronRight size={18} />
                            </button>
                          </div>

                          <div className="image-dots">
                            {project.images.map((_, i) => (
                              <button
                                key={i}
                                type="button"
                                className={`image-dot ${i === imageIndex ? 'active-dot' : ''}`}
                                onClick={() => setImageIndex(i)}
                                aria-label={`Go to image ${i + 1}`}
                              />
                            ))}
                          </div>
                        </>
                      )}
                    </>
                  ) : hasVideo ? (
                    <video className="project-video" controls preload="metadata">
                      <source src={project.video} type="video/mp4" />
                      Your browser does not support the video tag.
                    </video>
                  ) : (
                    <div className="project-image-placeholder">
                      <span>No screenshots available</span>
                    </div>
                  )}
                </div>
              </div>

              <div className="project-content">
                <h2 className="project-card-title">{project.title}</h2>
                <p className="project-card-description">{project.description}</p>

                <div className="project-section">
                  <h3 className="section-label">Key Features</h3>
                  <ul className="features-list">
                    {project.features.map((feature, i) => (
                      <li key={i}>
                        <span className="feature-icon">
                          <Check size={14} />
                        </span>
                        <span>{feature}</span>
                      </li>
                    ))}
                  </ul>
                </div>

                <div className="project-section">
                  <h3 className="section-label">Tech Stack</h3>
                  <div className="tech-stack">
                    {project.techStack.map((tech, i) => (
                      <span key={i} className="tech-pill">
                        {tech}
                      </span>
                    ))}
                  </div>
                </div>

                <div className="project-actions">
                  <a
                    href={project.github}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="github-btn"
                  >
                    <Github size={18} />
                    <span>View on GitHub</span>
                  </a>
                </div>
              </div>
            </div>
          </motion.div>

          <button
            onClick={nextProject}
            className="carousel-btn carousel-btn-right"
            aria-label="Next project"
          >
            <ChevronRight size={24} />
          </button>
        </div>

        {lightboxOpen && hasImages && (
          <motion.div
            className="lightbox-overlay"
            onClick={closeLightbox}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.2 }}
          >
            <motion.div
              className="lightbox-content"
              onClick={(e) => e.stopPropagation()}
              initial={{ opacity: 0, scale: 0.96, y: 12 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              transition={{ duration: 0.25, ease: 'easeOut' }}
            >
              <button
                type="button"
                className="lightbox-close"
                onClick={closeLightbox}
                aria-label="Close enlarged image"
              >
                <X size={20} />
              </button>

              <img
                src={project.images[imageIndex]}
                alt={`${project.title} enlarged screenshot ${imageIndex + 1}`}
                className="lightbox-image"
              />

              {project.images.length > 1 && (
                <div className="lightbox-controls">
                  <button
                    type="button"
                    className="image-btn"
                    onClick={prevImage}
                    aria-label="Previous image"
                  >
                    <ChevronLeft size={18} />
                  </button>
                  <button
                    type="button"
                    className="image-btn"
                    onClick={nextImage}
                    aria-label="Next image"
                  >
                    <ChevronRight size={18} />
                  </button>
                </div>
              )}
            </motion.div>
          </motion.div>
        )}
      </div>
    </section>
  );
};

export default Projects;