import React, { useState } from 'react';
import './navbar.css';
import contactImg from '../../assets/contact.png';
import logo from '../../assets/IA Dev Logo.png';
import { Link } from 'react-scroll';
import menu from '../../assets/menu.png';

const Navbar = () => {
  const [showMenu, setShowMenu] = useState(false);

  const closeMenu = () => setShowMenu(false);

  return (
    <nav className="navbar">
      <div className="navbarInner">
        <div className="navBrand">
          <img src={logo} alt="Irfan Arshad logo" className="Logo" />
        </div>

        <div className="navMenu">
          <Link
            activeClass="active"
            to="intro"
            spy={true}
            smooth={true}
            offset={-90}
            duration={500}
            className="navMenuListItem"
          >
            Home
          </Link>
          <Link
            activeClass="active"
            to="skills"
            spy={true}
            smooth={true}
            offset={-90}
            duration={500}
            className="navMenuListItem"
          >
            What I Do
          </Link>
          <Link
            activeClass="active"
            to="projects"
            spy={true}
            smooth={true}
            offset={-90}
            duration={500}
            className="navMenuListItem"
          >
            Projects
          </Link>
          <Link
            activeClass="active"
            to="contact"
            spy={true}
            smooth={true}
            offset={-90}
            duration={500}
            className="navMenuListItem"
          >
            Contact
          </Link>
        </div>

        <button
          className="navMenuButton"
          onClick={() => {
            document.getElementById('contact').scrollIntoView({ behavior: 'smooth' });
          }}
        >
          <img src={contactImg} alt="" className="navMenuImg" />
          Let&apos;s Talk
        </button>

        <button
          className="mobMenuButton"
          type="button"
          aria-label="Toggle menu"
          onClick={() => setShowMenu(!showMenu)}
        >
          <img src={menu} alt="Menu" className="mobMenu" />
        </button>

        <div className={`navMenu2 ${showMenu ? 'showMenu' : ''}`}>
          <Link
            activeClass="active"
            to="intro"
            spy={true}
            smooth={true}
            offset={-90}
            duration={500}
            className="listItem"
            onClick={closeMenu}
          >
            Home
          </Link>
          <Link
            activeClass="active"
            to="skills"
            spy={true}
            smooth={true}
            offset={-90}
            duration={500}
            className="listItem"
            onClick={closeMenu}
          >
            What I Do
          </Link>
          <Link
            activeClass="active"
            to="projects"
            spy={true}
            smooth={true}
            offset={-90}
            duration={500}
            className="listItem"
            onClick={closeMenu}
          >
            Projects
          </Link>
          <Link
            activeClass="active"
            to="contact"
            spy={true}
            smooth={true}
            offset={-90}
            duration={500}
            className="listItem"
            onClick={closeMenu}
          >
            Contact
          </Link>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;